def get_adjacent_states(grid):
    # Get dimensions of the grid
    rows, cols = len(grid), len(grid[0])

    # Initialize an empty dictionary to store adjacent states and their corresponding costs
    adjacent_states = {}

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'X':  # If current state is the goal, skip it
                continue

            # Get all valid movements (cardinal directions)
            movements = [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]

            for movement in movements:
                new_i, new_j = movement

                # Check if the new position is within grid boundaries
                if 0 <= new_i < rows and 0 <= new_j < cols:
                    adjacent_states[(new_i, new_j)] = abs(new_i - i) + abs(new_j - j)

    return list(adjacent_states.keys())

grid = [
    [0, 'X', 6],
    [1, 2, 4],
    ['X', 3, 5]
]

print(get_adjacent_states(grid))
